@page "/board"
@using sv_e1e7adc661fb4f61a9c7e7a53c86d265.Services
@inject ITaskService TaskService
@rendermode InteractiveServer

<PageTitle>Kanban Board</PageTitle>

<h3 class="mb-3">Kanban Board</h3>

@if (loading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (error is not null)
{
    <div class="alert alert-danger">
        <strong>Error:</strong> @error
        <button class="btn btn-outline-danger btn-sm ms-2" @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStatsBar TotalCount="filteredTasks.Count"
                   ToDoCount="toDoTasks.Count"
                   InProgressCount="inProgressTasks.Count"
                   DoneCount="doneTasks.Count"
                   OverdueCount="overdueTasks.Count" />

    <BoardSearchBar SearchText="@searchText" SearchTextChanged="OnSearchChanged" />

    <div class="row g-3">
        <BoardColumn ColumnName="To Do"
                     Tasks="toDoTasks"
                     ShowMoveLeft="false"
                     ShowMoveRight="true"
                     OnMoveRight="task => MoveTask(task, &quot;In Progress&quot;)"
                     OnTaskCreated="formData => CreateTask(formData, &quot;To Do&quot;)" />

        <BoardColumn ColumnName="In Progress"
                     Tasks="inProgressTasks"
                     ShowMoveLeft="true"
                     ShowMoveRight="true"
                     OnMoveLeft="task => MoveTask(task, &quot;To Do&quot;)"
                     OnMoveRight="task => MoveTask(task, &quot;Done&quot;)"
                     OnTaskCreated="formData => CreateTask(formData, &quot;In Progress&quot;)" />

        <BoardColumn ColumnName="Done"
                     Tasks="doneTasks"
                     ShowMoveLeft="true"
                     ShowMoveRight="false"
                     OnMoveLeft="task => MoveTask(task, &quot;In Progress&quot;)"
                     OnTaskCreated="formData => CreateTask(formData, &quot;Done&quot;)" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private string searchText = "";
    private bool loading = true;
    private string? error;

    private List<TaskItem> filteredTasks => allTasks
        .Where(t => string.IsNullOrEmpty(searchText)
            || t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase))
        .ToList();

    private List<TaskItem> toDoTasks => filteredTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> inProgressTasks => filteredTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> doneTasks => filteredTasks.Where(t => t.Status == "Done").ToList();
    private int overdueTasks => filteredTasks.Count(t => t.DueDate.Date < DateTime.Today);

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        loading = true;
        error = null;
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            error = ex.Message;
        }
        finally
        {
            loading = false;
        }
    }

    private void OnSearchChanged(string value)
    {
        searchText = value;
    }

    private async Task MoveTask(TaskItem task, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = allTasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
            {
                allTasks[index] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            error = ex.Message;
        }
    }

    private async Task CreateTask(TaskItem formData, string status)
    {
        try
        {
            var created = await TaskService.CreateTaskAsync(
                formData.Title, formData.Assignee, formData.Priority, formData.DueDate);
            allTasks.Add(created with { Status = status });
        }
        catch (Exception ex)
        {
            error = ex.Message;
        }
    }
}

